def transforms(S):
    out=[]
    for refl in [False,True]:
        for k in range(4):
            a=[]
            for r,c in S:
                if refl: c=-c
                for _ in range(k): r,c=c,-r
                a.append((r,c))
            minr=min(r for r,c in a); minc=min(c for r,c in a)
            norm=frozenset((r-minr,c-minc) for r,c in a)
            if norm not in [x[0] for x in out]: out.append((norm,(refl,k)))
    return out
